def compute(vars):
    total_transaction_value = vars["v1"]
    cash_consideration = vars["v2"]
    non_cash_assets = total_transaction_value - cash_consideration

    return {
        "value": round(non_cash_assets),
        "trace": {
            "total_transaction_value": total_transaction_value,
            "cash_consideration": cash_consideration,
            "non_cash_assets": non_cash_assets,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "monetary"
            }
        }
    }
